<?php
ob_start();
$_SERVER['CI_ENVIRONMENT']='development';
require dirname(__DIR__,2).'/vendor/codeigniter4/framework/system/util_bootstrap.php';
config('App')->baseURL='https://gereh.test/';
config('Database')->default=['DSN'=>'','database'=>':memory:','DBDriver'=>'SQLite3','DBPrefix'=>'','pConnect'=>false,'DBDebug'=>true,'charset'=>'utf8','DBCollat'=>'','swapPre'=>'','failover'=>[],'foreignKeys'=>true,'busyTimeout'=>1000,'dateFormat'=>['date'=>'Y-m-d','datetime'=>'Y-m-d H:i:s','time'=>'H:i:s']];
$db=\Config\Database::connect();if($db->DBDriver!=='SQLite3'||$db->database!==':memory:')throw new RuntimeException('Memory DB required');
$check=static function($condition,$label){if(!$condition)throw new RuntimeException($label);echo 'PASS '.$label.PHP_EOL;};
$seo=new \App\Services\SeoService();
$check($seo->page('shop',['page'=>2])['canonical']==='https://gereh.test/shop?page=2','Pagination self canonical');
$check($seo->page('shop',['brand'=>'asics','utm_source'=>'test'])['canonical']==='https://gereh.test/shop?brand=asics','Brand landing canonical removes tracking');
$check(str_starts_with($seo->page('shop',['size'=>'41'])['robots'],'noindex'),'Size filter noindex');
$check(str_starts_with($seo->page('blog',['q'=>'shoe'])['robots'],'noindex'),'Internal search noindex');
$check(str_starts_with($seo->page('account')['robots'],'noindex'),'Private page noindex');
$p=['slug'=>'test-shoe','name'=>'Test','price_toman'=>100,'short_description'=>'Description','brand_name'=>'ASICS','item_condition'=>'new'];
$schema=$seo->product($p,[['sku'=>'T-1','price_toman'=>100,'stock'=>0]],[]);
$check($schema['offers']['price']===1000 && $schema['offers']['priceCurrency']==='IRR','Toman price converted to IRR schema');
$check(str_ends_with($schema['offers']['availability'],'OutOfStock'),'Sold products keep honest stock schema');
$check(!isset($schema['aggregateRating']),'No fabricated ratings');
$check(!isset($seo->product($p,[['sku'=>'T-1','price_toman'=>0,'stock'=>1]],[])['offers']),'Missing price has no invalid offer');
$db->query('CREATE TABLE products (id INTEGER PRIMARY KEY,name TEXT,slug TEXT,status TEXT,price_toman INTEGER,deleted_at TEXT,updated_at TEXT)');
$db->table('products')->insertBatch([['id'=>1,'name'=>'Published','status'=>'active','price_toman'=>100,'deleted_at'=>null],['id'=>2,'name'=>'Draft','status'=>'draft','price_toman'=>100,'deleted_at'=>null],['id'=>3,'name'=>'No price','status'=>'draft','price_toman'=>0,'deleted_at'=>null]]);
require APPPATH.'Database/Migrations/2026-11-16-140000_AddProductEngagement.php';
(new \App\Database\Migrations\AddProductEngagement())->up();
$service=new \App\Services\ProductEngagementService($db);$check($service->ready(),'Engagement migration installs tables');
$service->recordView(1,'Mozilla/5.0');$service->recordView(1,'Mozilla/5.0');
$check($service->stats(1)['views']===1,'Repeated session view counted once within 30 minutes');
session()->remove('product_view_1');$service->recordView(1,'Googlebot');$check($service->stats(1)['views']===1,'Known crawler does not increment view');
$service->submit(1,'Reader','Useful product',5);$check(count($service->comments(1))===0,'New comments wait for moderation');
$id=(int)$db->insertID();$service->moderate($id,'approved');$check(count($service->comments(1))===1 && $service->stats(1)['rating_count']===1,'Approved comment is visible and counted');
$service->moderate($id,'rejected');$check(count($service->comments(1))===0 && $service->stats(1)['rating_count']===0,'Rejected comment removed from public rating');
$failed=false;try{$service->submit(2,'Reader','Draft comment',5);}catch(InvalidArgumentException $e){$failed=true;}$check($failed,'Draft product rejects public comment');
$dashboard=$service->dashboard();$check($dashboard['today_views']===1 && $dashboard['total_views']===1 && $dashboard['top_products'][0]['id']===1,'Dashboard reports real visits and ranked products');
$db->table('product_daily_views')->insert(['product_id'=>2,'day'=>date('Y-m-d',strtotime('-10 days')),'views'=>50]);
$dashboard=$service->dashboard();$check($dashboard['total_views']===51 && $dashboard['week_views']===1 && count($dashboard['top_products'])===1,'Dashboard separates lifetime totals from seven day ranking');
$catalog=new \App\Services\CatalogService($db);$catalog->setProductStatus(1,'archived');$catalog->setProductStatus(1,'draft');$catalog->setProductStatus(1,'active');
$check($db->table('products')->where('id',1)->get()->getRowArray()['status']==='active','Product status transitions persist');
$failed=false;try{$catalog->setProductStatus(3,'active');}catch(RuntimeException $e){$failed=true;}$check($failed,'Cannot publish product without a price');
$request=new \CodeIgniter\HTTP\IncomingRequest(config('App'),new \CodeIgniter\HTTP\SiteURI(config('App'),'shop'),null,new \CodeIgniter\HTTP\UserAgent());\Config\Services::injectMock('request',$request);
$html=view('store/partials/seo_head',['title'=>'Shop','description'=>'Description']);$check(substr_count($html,'rel="canonical"')===1 && str_contains($html,'og:locale'),'SSR SEO head contains canonical and social metadata');
$request=new \CodeIgniter\HTTP\IncomingRequest(config('App'),new \CodeIgniter\HTTP\SiteURI(config('App'),'account'),null,new \CodeIgniter\HTTP\UserAgent());
$response=service('response');(new \App\Filters\SeoHeaders())->after($request,$response);$check($response->getHeaderLine('X-Robots-Tag')==='noindex, nofollow','Private response has robots header');
$request=new \CodeIgniter\HTTP\IncomingRequest(config('App'),new \CodeIgniter\HTTP\SiteURI(config('App'),'product/test-shoe'),null,new \CodeIgniter\HTTP\UserAgent());\Config\Services::injectMock('request',$request);
$html=view('store/product',['product'=>$p+['id'=>1,'meta_title'=>null,'meta_description'=>null,'description'=>'Description','compare_at_price_toman'=>null],'variants'=>[],'media'=>[],'comments'=>[],'engagementReady'=>true]);
$check(substr_count($html,'rel="canonical"')===1 && str_contains($html,'name="author_name"'),'Actual product template renders SEO and public comment form');
$check(str_contains($html,'name="robots"') && str_contains($html,'application/ld+json'),'Full product HTML has server-rendered SEO data');
